function me = ElementLHS4ConPen_FR(nnpe,nqptv,wtq,qpmetric,gij_matrix,bigN,bigNprime,detj,dampfac)%  called by OrMonics and by FitOrientationDistributionWithHarmonics%% forms elemental LHS  matrix for determination of discrete harmonic%   functions and for fitting of coefficients to distributionsiend=nnpe;me = zeros(iend,iend);                                       for   k=1:1:nqptv       bigNqp = bigN(:,k)';    bigNprimeqp = bigNprime(:,:,k);    qp_gij_matrix(:,:) = gij_matrix(:,:,k);                                     xkfac(k)=wtq(k)*detj(k)*qpmetric(k);    me = me + xkfac(k)*(bigNqp' * bigNqp + dampfac * bigNprimeqp' *qp_gij_matrix*  bigNprimeqp);      end